daukle.plugin{ api = 1, uses = {} }

daukle.toolchain{
  name = "banner",
  generate = function(context)
    local config = context.config
    local features = config.features or {}
    local lines = {
      "/* Generated by the banner toolchain. Do not edit. */",
      '#define BUILD_MODE "' .. (config.mode or "release") .. '"',
      "#define FEATURE_COUNT " .. #features,
    }
    for index = 1, #features do
      lines[#lines + 1] = "#define FEATURE_" .. string.upper(features[index]) .. " 1"
    end
    return { ["banner.h"] = table.concat(lines, "\n") .. "\n" }
  end,
}
